(3175947, 446099, 41206, '<td valign="top">too much out of focus foreground IMO...a 5 for your effort.</td>', 'too much out of focus foreground IMO...a 5 for your effort.', '2007-01-03 13:47:10.000000', NULL, 1),
(3175950, 444937, 41206, '<td valign="top">needs a bit more fill light on her face...but a 5 anyway</td>', 'needs a bit more fill light on her face...but a 5 anyway', '2007-01-03 13:48:16.000000', NULL, 1),
