(3182524, 446653, 70021, '<td valign="top">Very cool.</td>', 'Very cool.', '2007-01-04 19:41:59.000000', NULL, 1),
(3182592, 444475, 55837, '<td valign="top">This is a really cool image.  I love tone mapping.  It doesn''t always work for me in a lot of photographs, but this one is excellent.  I don''t know if I see a ribbon, but in the top 20% is my prediction.</td>', 'This is a really cool image.  I love tone mapping.  It doesn''t always work for me in a lot of photographs, but this one is excellent.  I don''t know if I see a ribbon, but in the top 20% is my prediction.', '2007-01-04 19:56:49.000000', NULL, 1),
(3182595, 446761, 71274, '<td valign="top">Love the contrast and colors.</td>', 'Love the contrast and colors.', '2007-01-04 19:57:43.000000', NULL, 1),
(3182605, 445725, 55837, '<td valign="top">Spell check shows Corrall spelled "Corral".  I had to look twice.  Nice DOF showing the fence in background too.</td>', 'Spell check shows Corrall spelled "Corral".  I had to look twice.  Nice DOF showing the fence in background too.', '2007-01-04 19:59:26.000000', NULL, 1),
