(3183644, 446276, 61413, '<td valign="top">A nice idea. But I think you need more DOF on the fence itself, and maybe compose the shot with the boundary between the fence and the other elemenets on the right not quite so central.</td>', 'A nice idea. But I think you need more DOF on the fence itself, and maybe compose the shot with the boundary between the fence and the other elemenets on the right not quite so central.', '2007-01-05 00:31:36.000000', NULL, 1),
(3183667, 445204, 71045, '<td valign="top">Great color in this shot!  Nice DOF.  Composition is almost centered but its broken up by the curve of the wire...very interesting!  I would have cloned out that one single blade of grass that is paralles to the tree trunk.  Overall a great photo!</td>', 'Great color in this shot!  Nice DOF.  Composition is almost centered but its broken up by the curve of the wire...very interesting!  I would have cloned out that one single blade of grass that is paralles to the tree trunk.  Overall a great photo!', '2007-01-05 00:41:54.000000', NULL, 1),
(3183727, 444880, 35613, '<td valign="top">I can not see anything.</td>', 'I can not see anything.', '2007-01-05 01:13:23.000000', NULL, 1),
(3183849, 446735, 62727, '<td valign="top">LOL!  A horse with a sense of humor!</td>', 'LOL!  A horse with a sense of humor!', '2007-01-05 02:26:39.000000', NULL, 1),
(3183918, 444475, 6804, '<td valign="top">Beautiful scene!  The processing is a little over-done for my taste.  I do like the detail you have managed to bring out without the over sharpened look. Over-all a very nice shot.</td>', 'Beautiful scene!  The processing is a little over-done for my taste.  I do like the detail you have managed to bring out without the over sharpened look. Over-all a very nice shot.', '2007-01-05 03:26:24.000000', NULL, 1),
