(3190088, 443393, 36999, '<td valign="top">Nice field but the stone wall is a bit hidden by the perspective</td>', 'Nice field but the stone wall is a bit hidden by the perspective', '2007-01-07 00:25:11.000000', NULL, 1),
(3190148, 446226, 70308, '<td valign="top">This shot has a nice sense of depth to the fence and the left hand blur is nice.  Its also interesting that it stops at the center of the frame and trys to use negative space on the left.  Although I think it could have used perhaps a tighter crop as once I move left I lose the feeling I get from the right of the frame.  Thanks for sharing.</td>', 'This shot has a nice sense of depth to the fence and the left hand blur is nice.  Its also interesting that it stops at the center of the frame and trys to use negative space on the left.  Although I think it could have used perhaps a tighter crop as once I move left I lose the feeling I get from the right of the frame.  Thanks for sharing.', '2007-01-07 00:48:47.000000', NULL, 1),
(3190163, 443526, 53316, '<td valign="top">Not in focus, but I actually find that the lack of focus helps simplify what would otherwise be a perhaps-too-busy image for me.</td>', 'Not in focus, but I actually find that the lack of focus helps simplify what would otherwise be a perhaps-too-busy image for me.', '2007-01-07 00:54:58.000000', NULL, 1),
(3190167, 446431, 70308, '<td valign="top">I really enjoy the central composition and the slight vignetting on the edges of the frame which draw attention to the barb.  The reflections on the water droplets along the web are also a nice leading line taking my eyes across the wire.  Thanks for sharing.</td>', 'I really enjoy the central composition and the slight vignetting on the edges of the frame which draw attention to the barb.  The reflections on the water droplets along the web are also a nice leading line taking my eyes across the wire.  Thanks for sharing.', '2007-01-07 00:55:49.000000', NULL, 1),
(3190181, 444236, 53316, '<td valign="top">Mmmm... this image reminds me of the theme song to Firefly.<br/> <br/><i>Take my love, take my land<br/>Take me where I cannot stand<br/>I don''t care, I''m still free<br/>You can''t take the sky from me<br/>Take me out to the black<br/>Tell them I ain''t comin'' back<br/>Burn the land and boil the sea<br/>You can''t take the sky from me<br/>There''s no place I can be<br/>Since I found Serenity<br/>But you can''t take the sky from me</i> <br/> <br/>A good image for the emotions it envokes but also for colors and contrast, and wonderful composition.</td>', 'Mmmm... this image reminds me of the theme song to Firefly. Take my love, take my landTake me where I cannot standI don''t care, I''m still freeYou can''t take the sky from meTake me out to the blackTell them I ain''t comin'' backBurn the land and boil the seaYou can''t take the sky from meThere''s no place I can beSince I found SerenityBut you can''t take the sky from me  A good image for the emotions it envokes but also for colors and contrast, and wonderful composition.', '2007-01-07 00:59:23.000000', NULL, 1),
(3190187, 446444, 53316, '<td valign="top">AWESOME.  A beautiful image and a good example of grain used for a nice effect.  I like it.</td>', 'AWESOME.  A beautiful image and a good example of grain used for a nice effect.  I like it.', '2007-01-07 01:00:16.000000', NULL, 1),
(3190192, 443557, 53316, '<td valign="top">Not a fan of the selective desat here, but I do like the composition a lot, and the colors of the fence and related objects are very nice.</td>', 'Not a fan of the selective desat here, but I do like the composition a lot, and the colors of the fence and related objects are very nice.', '2007-01-07 01:02:32.000000', NULL, 1),
(3190197, 446607, 53316, '<td valign="top">Very Hitchhiker''s Guide-esque.  Not a bad thing at all if that wasn''t what you were going for, but if it was, then CONGRATS for doing it superbly.</td>', 'Very Hitchhiker''s Guide-esque.  Not a bad thing at all if that wasn''t what you were going for, but if it was, then CONGRATS for doing it superbly.', '2007-01-07 01:03:24.000000', NULL, 1),
(3190200, 445743, 53316, '<td valign="top">I like the colors a ton, and the lower contrast seems to work very well here for me.</td>', 'I like the colors a ton, and the lower contrast seems to work very well here for me.', '2007-01-07 01:04:01.000000', NULL, 1),
(3190207, 444039, 35350, '<td valign="top">She has the tiniest hint of a smail in those eyes that give her away even with the fenced in look.</td>', 'She has the tiniest hint of a smail in those eyes that give her away even with the fenced in look.', '2007-01-07 01:06:16.000000', NULL, 1),
(3190218, 444997, 9581, '<td valign="top">Moooo, this is great..</td>', 'Moooo, this is great..', '2007-01-07 01:13:55.000000', NULL, 1),
(3190438, 446620, 38648, '<td valign="top">not really sure what this has to do with the challenge, however, nice mask</td>', 'not really sure what this has to do with the challenge, however, nice mask', '2007-01-07 02:35:28.000000', NULL, 1),
(3190520, 445202, 66816, '<td valign="top">This was my favorite photo in the whole contest. I''m surprised you were the only person who took a photo of someone sitting on a fence! And you were one of the few who took pictures of city fences. And that''s where most fences are, anyway. Just staring at this photo is a pleasure... the colors are like eye candy, and it''s just a very pensive image. 10.</td>', 'This was my favorite photo in the whole contest. I''m surprised you were the only person who took a photo of someone sitting on a fence! And you were one of the few who took pictures of city fences. And that''s where most fences are, anyway. Just staring at this photo is a pleasure... the colors are like eye candy, and it''s just a very pensive image. 10.', '2007-01-07 04:47:07.000000', NULL, 1),
(3190612, 444698, 71268, '<td valign="top">Looks to unreal for my taste.</td>', 'Looks to unreal for my taste.', '2007-01-07 06:02:25.000000', NULL, 1);
