(3196731, 444911, 58610, '<td valign="top">Beautiful colors. Perhaps a little tighter crop on the pheasant would keep this from being so busy. I think you could easliy have cropped out most of the bush on the left without hurting the composition.</td>', 'Beautiful colors. Perhaps a little tighter crop on the pheasant would keep this from being so busy. I think you could easliy have cropped out most of the bush on the left without hurting the composition.', '2007-01-08 15:59:36.000000', NULL, 1),
(3196746, 446526, 58610, '<td valign="top">Very nice composition, but your highlights are definitely blown out. Did you try bringing them down with curves or levels?</td>', 'Very nice composition, but your highlights are definitely blown out. Did you try bringing them down with curves or levels?', '2007-01-08 16:01:44.000000', NULL, 1),
(3196764, 445380, 58610, '<td valign="top">A greater dof would add a  lot to this composition. Also, you have a very dramtic sky there. Use your editing tools to bring it out.</td>', 'A greater dof would add a  lot to this composition. Also, you have a very dramtic sky there. Use your editing tools to bring it out.', '2007-01-08 16:05:07.000000', NULL, 1),
(3196800, 445854, 58610, '<td valign="top">I like the feel of this photo a lot. What does that say about me? Your sky is very dramatic. Why not bring that out a little more?</td>', 'I like the feel of this photo a lot. What does that say about me? Your sky is very dramatic. Why not bring that out a little more?', '2007-01-08 16:11:05.000000', NULL, 1),
(3196811, 444075, 58610, '<td valign="top">Not sure I understand the shallow dof in this shot. I feel like I just barely got introduced, and then they were gone.</td>', 'Not sure I understand the shallow dof in this shot. I feel like I just barely got introduced, and then they were gone.', '2007-01-08 16:12:56.000000', NULL, 1),
(3196818, 446281, 58610, '<td valign="top">Very bleak feeling, here. Might even have been a good candidate for B&amp;W. Love the maple leaf in the gate - very clear where this was taken.</td>', 'Very bleak feeling, here. Might even have been a good candidate for B&W. Love the maple leaf in the gate - very clear where this was taken.', '2007-01-08 16:14:31.000000', NULL, 1),
(3196821, 445402, 58610, '<td valign="top">Excellent. Very scary feel.</td>', 'Excellent. Very scary feel.', '2007-01-08 16:15:05.000000', NULL, 1),
(3196824, 445093, 58610, '<td valign="top">I like the bokeh effect in this shot.  The photo is well framed with a strong composition.</td>', 'I like the bokeh effect in this shot.  The photo is well framed with a strong composition.', '2007-01-08 16:17:16.000000', NULL, 1),
