(3196842, 446276, 58610, '<td valign="top">Either more or less of the fence. Splitting it down the center doesn''t work all that well.</td>', 'Either more or less of the fence. Splitting it down the center doesn''t work all that well.', '2007-01-08 16:21:24.000000', NULL, 1),
(3196850, 445746, 58610, '<td valign="top">Wonderful silhouette.  I can feel the wind rushing by.</td>', 'Wonderful silhouette.  I can feel the wind rushing by.', '2007-01-08 16:26:18.000000', NULL, 1),
(3196856, 444579, 58610, '<td valign="top">Maybe just a little heavy toward the blue, but very cold  feeling, and, yet, still some warmth, too. Good shot.</td>', 'Maybe just a little heavy toward the blue, but very cold  feeling, and, yet, still some warmth, too. Good shot.', '2007-01-08 16:28:36.000000', NULL, 1),
(3196859, 443475, 22937, '<td valign="top">The post processing method or filter used do not give the shot justice. A well above 5 shot is IMHO below average due to your post processing. Keep up the good work though!</td>', 'The post processing method or filter used do not give the shot justice. A well above 5 shot is IMHO below average due to your post processing. Keep up the good work though!', '2007-01-08 16:31:54.000000', NULL, 1),
(3196878, 445696, 58610, '<td valign="top">I''d like to see it with a darker sky. Otherwise, good exposure - just enought detail  in the fence to make it stand out.</td>', 'I''d like to see it with a darker sky. Otherwise, good exposure - just enought detail  in the fence to make it stand out.', '2007-01-08 16:37:52.000000', NULL, 1),
(3196898, 446665, 58610, '<td valign="top">Hard to see what your subject is. Now that I look a little harder I do see the bird''s nest. Focusing our attention on the nest takes our interest away from the "true" subject of this photo, which should be the fence.</td>', 'Hard to see what your subject is. Now that I look a little harder I do see the bird''s nest. Focusing our attention on the nest takes our interest away from the "true" subject of this photo, which should be the fence.', '2007-01-08 16:42:24.000000', NULL, 1),
(3196916, 445195, 58610, '<td valign="top">Nice scene, but the composition doesn''t quite work. Moving the ''center'' of the photo either left or right would create much more visual interest.</td>', 'Nice scene, but the composition doesn''t quite work. Moving the ''center'' of the photo either left or right would create much more visual interest.', '2007-01-08 16:46:06.000000', NULL, 1),
(3196926, 445345, 58610, '<td valign="top">Very nice shot. The tree line echos the fence lines wonderfully. Such a bleak and dreary feeling you''ve captured.</td>', 'Very nice shot. The tree line echos the fence lines wonderfully. Such a bleak and dreary feeling you''ve captured.', '2007-01-08 16:49:20.000000', NULL, 1),
