(3198025, 446635, 69407, '<td valign="top">Love the title and the guinea pig - but there seems to be some weird glares going on? This might be making the right side look a little washed out?</td>', 'Love the title and the guinea pig - but there seems to be some weird glares going on? This might be making the right side look a little washed out?', '2007-01-08 22:04:37.000000', NULL, 1),
(3198029, 444826, 69407, '<td valign="top">The frame on this makes the picture seem more fuzzy or misty by contrast... not sure if that was the intention? Love the line the fence creates here, though - great angle! Gives a nice flow overall, just wish it was clearer.</td>', 'The frame on this makes the picture seem more fuzzy or misty by contrast... not sure if that was the intention? Love the line the fence creates here, though - great angle! Gives a nice flow overall, just wish it was clearer.', '2007-01-08 22:06:38.000000', NULL, 1),
(3198034, 446120, 69407, '<td valign="top">The implied textures and details of this poor battered sign are very dramatic The focus the way it is makes me feel there should be something in the background as the focus. The crop is great, too, reminds me of comic books.</td>', 'The implied textures and details of this poor battered sign are very dramatic The focus the way it is makes me feel there should be something in the background as the focus. The crop is great, too, reminds me of comic books.', '2007-01-08 22:08:24.000000', NULL, 1),
(3198508, 443972, 34938, '<td valign="top">this is superb, like a painting...I love the shadows on the image and the look on the cow''s face...the selective desat is a genius stroke...was going to give this 9, but will go all the way to 10...good luck</td>', 'this is superb, like a painting...I love the shadows on the image and the look on the cow''s face...the selective desat is a genius stroke...was going to give this 9, but will go all the way to 10...good luck', '2007-01-09 00:27:25.000000', NULL, 1),
