(3200366, 445174, 69183, '<td valign="top">I''d have cropped this a bit more on the left so that the fence met the corners of the shot, rather than letting it continue. Nice though.</td>', 'I''d have cropped this a bit more on the left so that the fence met the corners of the shot, rather than letting it continue. Nice though.', '2007-01-09 12:48:27.000000', NULL, 1),
(3200379, 445164, 69183, '<td valign="top">Grrr. This photo made me notice a stuck pixel on my screen. Love the shot tho, very nice.</td>', 'Grrr. This photo made me notice a stuck pixel on my screen. Love the shot tho, very nice.', '2007-01-09 12:51:08.000000', NULL, 1),
(3200405, 443557, 54728, '<td valign="top">Very nice selective desaturation...I love the contrast between the warm colours of the decaying fence and life preserver and the cold gray of the factories.</td>', 'Very nice selective desaturation...I love the contrast between the warm colours of the decaying fence and life preserver and the cold gray of the factories.', '2007-01-09 12:58:06.000000', NULL, 1),
(3200409, 444360, 69183, '<td valign="top">This could be really good, but the rocky objects are totally black and have no detail so I can''t work out what they are or why they''re restricted. Sorry.</td>', 'This could be really good, but the rocky objects are totally black and have no detail so I can''t work out what they are or why they''re restricted. Sorry.', '2007-01-09 13:00:10.000000', NULL, 1),
(3200413, 446660, 69183, '<td valign="top">There are some really big chunks here that just aren''t in focus, like the lens has raindrops on it or something. I find this really difficult to get a handle on.</td>', 'There are some really big chunks here that just aren''t in focus, like the lens has raindrops on it or something. I find this really difficult to get a handle on.', '2007-01-09 13:02:53.000000', NULL, 1),
(3200416, 445184, 58610, '<td valign="top">I like the flow in this picture. You really have the sense of motion.</td>', 'I like the flow in this picture. You really have the sense of motion.', '2007-01-09 13:04:37.000000', NULL, 1),
(3200421, 446065, 69183, '<td valign="top">spectacular. Very well framed, excellent lighting. Came back again to give it a 10.</td>', 'spectacular. Very well framed, excellent lighting. Came back again to give it a 10.', '2007-01-09 13:06:38.000000', NULL, 1),
(3200424, 446065, 58610, '<td valign="top">You took a pretty crappy background and turned it into a very successful picture. Good job on pp.</td>', 'You took a pretty crappy background and turned it into a very successful picture. Good job on pp.', '2007-01-09 13:07:24.000000', NULL, 1),
(3200426, 446681, 69183, '<td valign="top">Nice. One of the best "sample of some barbed wire" shots so far.</td>', 'Nice. One of the best "sample of some barbed wire" shots so far.', '2007-01-09 13:08:08.000000', NULL, 1),
(3200436, 444507, 58610, '<td valign="top">Lots going on, and maybe a little too busy, but I like your idea very much. Perhaps a little oversaturated as well.</td>', 'Lots going on, and maybe a little too busy, but I like your idea very much. Perhaps a little oversaturated as well.', '2007-01-09 13:13:08.000000', NULL, 1),
