(3205754, 443779, 69008, '<td valign="top">The way you lined up with the foreground and primary subject in the corner gives this a refreshing touch. <br/>The color is lovely too. <br/>Berry nice!</td>', 'The way you lined up with the foreground and primary subject in the corner gives this a refreshing touch. The color is lovely too. Berry nice!', '2007-01-10 11:11:31.000000', NULL, 0),
(3205785, 446504, 58728, '<td valign="top">Hello from a teammate!  I really like this shot as well.  I personally would have liked to see a tighter crop on the cows....they seem a tad far away...IMO.  Also, maybe if you had tweaked the colors a little bit more, it may look brighter.  Overall it''s a really nice shot.  ~Magen</td>', 'Hello from a teammate!  I really like this shot as well.  I personally would have liked to see a tighter crop on the cows....they seem a tad far away...IMO.  Also, maybe if you had tweaked the colors a little bit more, it may look brighter.  Overall it''s a really nice shot.  ~Magen', '2007-01-10 11:18:43.000000', NULL, 0),
(3206298, 444620, 66038, '<td valign="top">this far and away my favorite entry. It has a great feel and and a look of mystery and subtle allure.<br/> Good job.</td>', 'this far and away my favorite entry. It has a great feel and and a look of mystery and subtle allure. Good job.', '2007-01-10 12:47:26.000000', NULL, 0),
(3206396, 446447, 51846, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by lynnesite:</b></div><hr/><i> I don''t "get" your title, as I see what might be a gate, but I do really like the light you''ve got and the confluence of fence corners. </i></td></tr></table>  The ''61'' sign is the marker for the footpath.  That was why I used that title.</td>', 'Originally posted by lynnesite: I don''t "get" your title, as I see what might be a gate, but I do really like the light you''ve got and the confluence of fence corners.   The ''61'' sign is the marker for the footpath.  That was why I used that title.', '2007-01-10 13:10:30.000000', NULL, 0),
(3206511, 445866, 68388, '<td valign="top">I gave this a 9.  The only thing that bothered me is the way the lights lined up.  I looks like they''re leaning back a bit.  You can try adobe ps cs2 , go to filter--&gt; distort --&gt; lens correction and play with this photo a bit, and see what new results you get !<br/></td>', 'I gave this a 9.  The only thing that bothered me is the way the lights lined up.  I looks like they''re leaning back a bit.  You can try adobe ps cs2 , go to filter--> distort --> lens correction and play with this photo a bit, and see what new results you get !', '2007-01-10 13:30:35.000000', NULL, 0),
(3206520, 446431, 34659, '<td valign="top">Congratulations on your well-deserved ribbon!  This is a terrific shot and my top pick for this challenge.</td>', 'Congratulations on your well-deserved ribbon!  This is a terrific shot and my top pick for this challenge.', '2007-01-10 13:31:55.000000', NULL, 0),
(3206533, 446518, 68388, '<td valign="top">I gave this a 9.  I love this photo except that the subject is a bit dark.</td>', 'I gave this a 9.  I love this photo except that the subject is a bit dark.', '2007-01-10 13:34:15.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3206541, 446553, 34659, '<td valign="top">Looks like an HDR image to me.  Very cool shot with terrific PP.  Well done &amp; congratulations.</td>', 'Looks like an HDR image to me.  Very cool shot with terrific PP.  Well done & congratulations.', '2007-01-10 13:35:12.000000', NULL, 0),
(3206655, 444739, 772, '<td valign="top">Congratulations on entering your first challenge :)  The challenge description is as follows:<br/> <br/>"The fences we are referring to are actual, physical fences; some are decorative, some are protective, some mark boundaries, some are for erosion control. Think about fences, and give us YOUR perspective :-)"<br/> <br/>Here at DPC, out-of-the-box interpretations of the topic and description aren''t usually great ideas for challenge photos.  There are occasions where they do well, but they must have some extremely strong element to pull them above the median score.  When a photo requires any significant thought to ''grasp'' in a challenge, it is an absolute requirement that the image provide a high level of ''eye candy'' to get the viewer to consider your interpretation a little deeper.  The high number of photos in any given challenge here keep people from spending more than a couple seconds looking at a photo.  With some eye candy in the image, you may get a little more thought about your idea.<br/> <br/>Think of a challenge as a ''game'' rather than an art competition.  It''s a game/contest where your own result is handed to you by your competition.  <br/> <br/>Good luck :)</td>', 'Congratulations on entering your first challenge :)  The challenge description is as follows: "The fences we are referring to are actual, physical fences; some are decorative, some are protective, some mark boundaries, some are for erosion control. Think about fences, and give us YOUR perspective :-)" Here at DPC, out-of-the-box interpretations of the topic and description aren''t usually great ideas for challenge photos.  There are occasions where they do well, but they must have some extremely strong element to pull them above the median score.  When a photo requires any significant thought to ''grasp'' in a challenge, it is an absolute requirement that the image provide a high level of ''eye candy'' to get the viewer to consider your interpretation a little deeper.  The high number of photos in any given challenge here keep people from spending more than a couple seconds looking at a photo.  With some eye candy in the image, you may get a little more thought about your idea. Think of a challenge as a ''game'' rather than an art competition.  It''s a game/contest where your own result is handed to you by your competition.   Good luck :)', '2007-01-10 13:52:24.000000', NULL, 0),
(3206827, 443360, 66097, '<td valign="top">Thank you for sharing this photo.  I immediately became saddened and tearful.  We must NEVER FORGET!!!</td>', 'Thank you for sharing this photo.  I immediately became saddened and tearful.  We must NEVER FORGET!!!', '2007-01-10 14:20:01.000000', NULL, 0),
(3206912, 445711, 56797, '<td valign="top">Beautiful shot. wonderful point of view, composition, lighting and processing. congrats on your 6. :)</td>', 'Beautiful shot. wonderful point of view, composition, lighting and processing. congrats on your 6. :)', '2007-01-10 14:32:31.000000', NULL, 0),
(3206919, 445711, 11897, '<td valign="top">A wonderful picture and a very respectable, well deserved placing,<br/>Paul. <br/></td>', 'A wonderful picture and a very respectable, well deserved placing,Paul. ', '2007-01-10 14:33:57.000000', NULL, 0),
(3206967, 445711, 30861, '<td valign="top">Far out! Nice use of fill flash. Way to ignore mom! Congrats on your first 6+!</td>', 'Far out! Nice use of fill flash. Way to ignore mom! Congrats on your first 6+!', '2007-01-10 14:45:38.000000', NULL, 0),
(3206979, 445854, 30861, '<td valign="top">Hey, nice job! Gives me the chills to look at it. "Dakota Ice" would have been a better title. It''s not a serious anonymity breaker at all; I do worse all the time. I might have called it "Ice Storm  Aftermath", but that''s just me... Congrats on top-10!</td>', 'Hey, nice job! Gives me the chills to look at it. "Dakota Ice" would have been a better title. It''s not a serious anonymity breaker at all; I do worse all the time. I might have called it "Ice Storm  Aftermath", but that''s just me... Congrats on top-10!', '2007-01-10 14:48:20.000000', NULL, 0),
(3206996, 445711, 34659, '<td valign="top">Congratulations on your first 6+ score.  I''m sure it won''t be the last.  Beautiful clarity &amp; tones in this shot.  Nice leading lines of composition too.  Well done!  (It scored a 7 from me during voting - the sky &amp; upper left portion of the shot are a little bright - but it is still a very good photo.)</td>', 'Congratulations on your first 6+ score.  I''m sure it won''t be the last.  Beautiful clarity & tones in this shot.  Nice leading lines of composition too.  Well done!  (It scored a 7 from me during voting - the sky & upper left portion of the shot are a little bright - but it is still a very good photo.)', '2007-01-10 14:51:36.000000', NULL, 0),
(3207077, 446065, 50864, '<td valign="top">Congratulations Marj. That is a beautiful shot and a well deserved ribbon.</td>', 'Congratulations Marj. That is a beautiful shot and a well deserved ribbon.', '2007-01-10 15:01:43.000000', NULL, 0),
(3207337, 446681, 6870, '<td valign="top">Hi Steve! It looks like you got some good comments! You may want to straighten your horizon (or make it more tilted, if you''re going for that effect). I like the positioning of the foggy sun just to the right of the barb. You may be able to play with colors to see if you can eek more drama into the shot. Nice work, though!</td>', 'Hi Steve! It looks like you got some good comments! You may want to straighten your horizon (or make it more tilted, if you''re going for that effect). I like the positioning of the foggy sun just to the right of the barb. You may be able to play with colors to see if you can eek more drama into the shot. Nice work, though!', '2007-01-10 15:30:30.000000', NULL, 0),
(3207475, 444704, 69934, '<td valign="top">Thank you for the kind words. I appreciate all of your votes.</td>', 'Thank you for the kind words. I appreciate all of your votes.', '2007-01-10 15:49:22.000000', NULL, 0),
(3207476, 446328, 28532, '<td valign="top">Sweet!! Congrats on 4th place - A beautiful image!</td>', 'Sweet!! Congrats on 4th place - A beautiful image!', '2007-01-10 15:49:24.000000', NULL, 0),
